fn native_photo_group(category:usize)->Vec<usize>{
    match category {
        0=>vec![64,65,66,68,69,70,72,73,77,74,24,29],
        1=>vec![64,65,66,67,68,69,70,71,72,73,75,77,78,79,24,25,43,50],
        2=>vec![29,30,31,39,47,56,57,10,18,17],
        3=>vec![64,68,69,70,71,73,75,76,77,79,1,5,8,14,22,34,36,40,42,48,52,53,61,62],
        4=>vec![10,19,20,32,33,38,49,54,55,59],
        5=>vec![80,81,82,65,67,74,77,78,2,3,4,6,9,11,12,17,23,35,38,46,58,59],
        _=>(0..crate::native_presets::PRESETS.len()).collect(),
    }
}
fn native_lighting_controls(app:&mut BoostApp,ui:&mut Ui){
    let mut tuning=app.settings.lighting.clone();
    let mut changed=false;
    frame(PANEL).show(ui,|ui|{
        ui.set_min_width(ui.available_width());
        ui.horizontal_wrapped(|ui|{
            heading(ui,"LIGHT STUDIO · LIVE GPU");
            if ui.checkbox(&mut tuning.enabled,"Enable").changed(){changed=true;}
            caption(ui,if tuning.enabled{"COLOR-ONLY LIGHTS ACTIVE WHEN WGC OUTPUT RUNS"}
                else{"OFF BY DEFAULT · DOES NOT MODIFY THE GAME"});
        });
        caption(ui,"Custom native shader: local highlight bloom, soft 2D contact contrast, color spill, edge detail and SDR filmic tone.");
        ui.add_space(5.0);
        ui.horizontal_wrapped(|ui|{
            for (label,vals) in [
                ("Natural",[0.24,0.25,0.21,0.16,0.24,0.10,0.74]),
                ("Cinematic",[0.56,0.32,0.17,0.20,0.56,0.23,0.85]),
                ("Shadow Pop",[0.76,0.16,0.32,0.33,0.21,0.08,0.87]),
                ("Radiance",[0.20,0.74,0.56,0.10,0.29,0.37,0.90]),
            ]{
                if outline_button(ui,label){
                    tuning.enabled=true;
                    [tuning.shadow,tuning.glow,tuning.bounce,tuning.detail,
                        tuning.film,tuning.warmth,tuning.mix]=vals;
                    changed=true;
                }
            }
            if outline_button(ui,"Reset to OFF"){
                let grade=tuning.grade.clone();let layers=tuning.layers.clone();let motion=tuning.motion.clone();let lut=tuning.lut.clone();let exposure=tuning.exposure.clone();let reconstruction=tuning.reconstruction.clone();let precision=tuning.precision.clone();let recipe=tuning.recipe.clone();let cinema=tuning.cinema.clone();let bypass_look=tuning.bypass_look;tuning=crate::lighting::LightTuning::default();tuning.grade=grade;tuning.layers=layers;tuning.motion=motion;tuning.lut=lut;tuning.exposure=exposure;tuning.reconstruction=reconstruction;tuning.precision=precision;tuning.recipe=recipe;tuning.cinema=cinema;tuning.bypass_look=bypass_look;
                changed=true;
            }
        });
        ui.add_enabled_ui(tuning.enabled,|ui|{
            ui.columns(2,|cols|{
                changed|=cols[0].add(egui::Slider::new(&mut tuning.shadow,0.0..=1.0)
                    .text("Contact shadows")).changed();
                changed|=cols[1].add(egui::Slider::new(&mut tuning.glow,0.0..=1.0)
                    .text("Highlight glow")).changed();
                changed|=cols[0].add(egui::Slider::new(&mut tuning.bounce,0.0..=1.0)
                    .text("Color bounce")).changed();
                changed|=cols[1].add(egui::Slider::new(&mut tuning.detail,0.0..=1.0)
                    .text("Fine detail")).changed();
                changed|=cols[0].add(egui::Slider::new(&mut tuning.film,0.0..=1.0)
                    .text("Filmic range")).changed();
                changed|=cols[1].add(egui::Slider::new(&mut tuning.warmth,0.0..=1.0)
                    .text("Sun warmth")).changed();
            });
            changed|=ui.add(egui::Slider::new(&mut tuning.mix,0.0..=1.0)
                .text("Overall intensity")).changed();
        });
        caption(ui,if app.native_mirror.as_ref().is_some_and(|m|m.running()){
            "LIVE: slider changes update GPU shader constants automatically, without restarting the game or output."
        }else{
            "Saved safely for the selected game. Start the native GPU preview / Glass to see moving light changes."
        });
        caption(ui,"Important: no depth/normals; cannot add true ray-traced light or cast correct object shadows. Captured HUD may also receive color effects.");
    });
    frame(PANEL).show(ui,|ui|{
        heading(ui,"CINEMA RADIANCE / MULTISCALE GPU LIGHT");
        caption(ui,"Independent three-stage linear-light screen-space illumination estimate. No engine hook, game files, geometry or real path tracing. RX 580 starts on Economy.");
        changed|=ui.checkbox(&mut tuning.cinema.enabled,"Enable Cinema Radiance").changed();
        changed|=ui.checkbox(&mut tuning.bypass_look,"Bypass selected native look (keep lighting)").changed();
        egui::CollapsingHeader::new("Look groups / HUD and fine-edge protection").show(ui,|ui|{
         ui.horizontal_wrapped(|ui|{for(i,n)in crate::layer_mix::GROUPS.iter().enumerate(){changed|=ui.checkbox(&mut tuning.layers.groups[i],*n).changed();}});
         if outline_button(ui,"Enable all groups"){tuning.layers.groups=[true;4];changed=true;}
         let p=&mut tuning.layers.protect;
         changed|=ui.checkbox(&mut p.rectangle,"Restore original HUD rectangle after all color effects").changed();
         if p.rectangle{
          for(i,n)in ["Left","Top","Right","Bottom"].iter().enumerate(){changed|=ui.add(egui::Slider::new(&mut p.rect[i],0.0..=1.).text(*n)).changed();}
         }
         changed|=ui.add(egui::Slider::new(&mut p.edge_strength,0.0..=1.).text("Fine edge protection")).changed();
         changed|=ui.add(egui::Slider::new(&mut p.edge_threshold,0.02..=0.8).text("Edge contrast threshold")).changed();
         caption(ui,"Restores input pixels of color pipeline, after look, LUT, Cinema, recipe, precision and A/B. No semantic text detector; spatial scaling and later motion processing may still change the output.");
         if outline_button(ui,"Reset protection"){*p=Default::default();changed=true;}
        });
        caption(ui,"Non-destructive: restores original look when unchecked. Other independent Light/Color/LUT/Precision effects still apply.");
        ui.horizontal_wrapped(|ui|{
         for(i,label)in ["Balanced","Deep shadows","Radiant color","Natural soft"].iter().enumerate(){if outline_button(ui,label){tuning.cinema=crate::cinema_light::Options::preset(i as u8);changed=true;}}
         if outline_button(ui,"Cinema off / reset"){tuning.cinema=Default::default();changed=true;}
        });
        ui.add_enabled_ui(tuning.cinema.enabled,|ui|{
         egui::ComboBox::from_id_salt("cinema-quality").selected_text(["Economy 1/8 field","Balanced 1/4 field","Fine 1/2 field"][tuning.cinema.quality.min(2) as usize]).show_ui(ui,|ui|{for(i,n)in ["Economy 1/8","Balanced 1/4","Fine 1/2"].iter().enumerate(){changed|=ui.selectable_value(&mut tuning.cinema.quality,i as u8,*n).changed();}});
         ui.columns(2,|cols|{
          changed|=cols[0].add(egui::Slider::new(&mut tuning.cinema.shadow,0.0..=1.).text("Contact shade")).changed();
          changed|=cols[1].add(egui::Slider::new(&mut tuning.cinema.bounce,0.0..=1.).text("Indirect color")).changed();
          changed|=cols[0].add(egui::Slider::new(&mut tuning.cinema.bloom,0.0..=1.).text("Light diffusion")).changed();
          changed|=cols[1].add(egui::Slider::new(&mut tuning.cinema.sheen,0.0..=1.).text("Edge sheen")).changed();
          changed|=cols[0].add(egui::Slider::new(&mut tuning.cinema.radius,0.0..=1.).text("Light reach")).changed();
          changed|=cols[1].add(egui::Slider::new(&mut tuning.cinema.exposure,0.0..=1.).text("Local exposure")).changed();
          changed|=cols[0].add(egui::Slider::new(&mut tuning.cinema.shoulder,0.0..=1.).text("Highlight rolloff")).changed();
          changed|=cols[1].add(egui::Slider::new(&mut tuning.cinema.mix,0.0..=1.).text("Master mix")).changed();
         });
         changed|=ui.checkbox(&mut tuning.cinema.protect_hud,"Respect Motion Studio HUD rectangle").changed();
         if tuning.cinema.protect_hud{
          changed|=ui.checkbox(&mut tuning.motion.mask,"Enable protected rectangle").changed();
          if tuning.motion.mask{
           changed|=ui.add(egui::Slider::new(&mut tuning.motion.left,0.0..=0.95).text("HUD left")).changed();
           changed|=ui.add(egui::Slider::new(&mut tuning.motion.top,0.0..=0.95).text("HUD top")).changed();
           let left=tuning.motion.left;let top=tuning.motion.top;
           changed|=ui.add(egui::Slider::new(&mut tuning.motion.right,(left+0.05)..=1.).text("HUD right")).changed();
           changed|=ui.add(egui::Slider::new(&mut tuning.motion.bottom,(top+0.05)..=1.).text("HUD bottom")).changed();
          }
         }
        });
        caption(ui,"Cinema preserves its input within the mask, not effects before/after this pass. Above 1080p the fine field is capped at 1/4. Reference Photo Lab supports A/B; added GPU cost, no FPS uplift promise.");

    });
    if changed{app.apply_native_lighting(tuning);}
}
