#[cfg(test)]
mod native_photo_gallery_tests{
    use super::*;
    #[test]fn reference_color_photo_is_real_pixel_transform_not_ai(){
        let img=image::RgbaImage::from_pixel(1,1,image::Rgba([200,40,190,255]));
        let unchanged=os_color_reference_pixels(img.clone(),7,0.0);
        assert_eq!(unchanged.get_pixel(0,0).0,img.get_pixel(0,0).0);
        let changed=os_color_reference_pixels(img.clone(),5,1.0);
        let p=changed.get_pixel(0,0);
        assert!(p[0].abs_diff(p[1])<=1&&p[1].abs_diff(p[2])<=1);
        assert_eq!(p[3],255);
    }
    #[test]fn all_native_photo_assets_exist_in_the_gallery(){
        assert_eq!(GPU_PHOTO_PREVIEWS.len(),crate::native_presets::PRESETS.len());
        assert_eq!(GPU_GAMEPLAY_PREVIEWS.len(),crate::native_presets::PRESETS.len());
        for bytes in GPU_GAMEPLAY_PREVIEWS{assert!(bytes.len()>20_000);}
        for bytes in GPU_PHOTO_PREVIEWS{assert!(bytes.len()>20_000);}
        for category in 0..NATIVE_GROUP_NAMES.len(){
            assert!(native_photo_group(category).iter().all(
                |i|*i<crate::native_presets::PRESETS.len()));
        }
    }
}

// The actual native rendering chain, not the archived Magpie stack.
fn native_stack_builder(app:&mut BoostApp,ui:&mut Ui){
    let key=app.profile_key();
    native_favorite_panel(app,ui);
    let mut tune=app.settings.lighting.clone();let mut mix_changed=false;
    let draft_id=ui.id().with(("native-stack-draft",key.as_str()));
    let active=app.settings.native_stack_profiles.get(&key).cloned();
    let preset=crate::native_presets::PRESETS[app.settings.native_preset].stages.to_vec();
    let mut draft=ui.ctx().data_mut(|d|d.get_temp::<Vec<usize>>(draft_id))
        .unwrap_or_else(||active.clone().unwrap_or(preset.clone()));
    let mut new_stage=ui.ctx().data_mut(|d|d.get_temp::<usize>(draft_id.with("new"))).unwrap_or(2);
    let mut history=ui.ctx().data_mut(|d|d.get_temp::<crate::stack_history::History>(draft_id.with("history"))).unwrap_or_default();
    let original_draft=draft.clone();
    let mut history_action=false;
    frame(PANEL).show(ui,|ui|{
        ui.set_min_width(ui.available_width());
        heading(ui,"NATIVE STACK BUILDER");
        ui.horizontal_wrapped(|ui|{for (label,ids) in [("Shadow mask",&[62usize][..]),("Curved arcade",&[63usize][..]),("CRT phosphor",&[19usize][..]),("Lens",&[23usize,48][..]),("Film",&[49usize,59][..])]{if outline_button(ui,label){draft=ids.to_vec();}}});
        caption(ui,"Input / ordered GPU effects / spatial scaler / Horizon DXGI output");
        ui.colored_label(if active.is_some(){V25_MINT}else{MUTED},
            if active.is_some(){"CUSTOM STACK SELECTED"}else{"USING STANDARD LOOK"});
        caption(ui,"Draft edits are local. Apply commits the sequence for this game; Full quality runs all stages. Light Studio remains separate.");
        ui.horizontal_wrapped(|ui|{
            if ui.add_enabled(history.can_undo(),egui::Button::new("Undo")).clicked(){
                if let Some(v)=history.undo(draft.clone()){draft=v;history_action=true;}
            }
            if ui.add_enabled(history.can_redo(),egui::Button::new("Redo")).clicked(){
                if let Some(v)=history.redo(draft.clone()){draft=v;history_action=true;}
            }
        });
        ui.add_space(8.0);
        let mut remove=None;let mut swap=None;
        for (i,stage) in draft.iter().enumerate(){
            frame(CARD).show(ui,|ui|{
                ui.set_min_width(ui.available_width());
                ui.horizontal_wrapped(|ui|{
                    ui.colored_label(RED,format!("{:02}",i+1));
                    let label=crate::native_filter::PROGRAMS.get(*stage).map(|s|s.0).unwrap_or("Invalid");
                    ui.label(label);
                    let applied=active.as_ref().unwrap_or(&preset)==&draft;
                    let mut mix=tune.layers.strength_at(&draft,i);
                    if ui.add_enabled(applied,egui::Slider::new(&mut mix,0.0..=1.0).text("Mix")).changed(){
                        tune.layers.set_at(&draft,i,mix);mix_changed=true;
                    }
                    if ui.add_enabled(applied,egui::Button::new(if mix==0.{"Enable"}else{"Bypass"})).clicked(){
                        tune.layers.set_at(&draft,i,if mix==0.{1.}else{0.});mix_changed=true;
                    }
                    if ui.add_enabled(i>0,egui::Button::new("Up")).clicked(){swap=Some((i,i-1));}
                    if ui.add_enabled(i+1<draft.len(),egui::Button::new("Down")).clicked(){swap=Some((i,i+1));}
                    if ui.small_button("Remove").clicked(){remove=Some(i);}
                });
            });
            ui.add_space(4.0);
        }
        if let Some((a,b))=swap{crate::native_stack::move_stage(&mut draft,a,b);}
        if let Some(i)=remove{draft.remove(i);}
        ui.horizontal_wrapped(|ui|{
            egui::ComboBox::from_id_salt("custom-native-add")
                .selected_text(crate::native_filter::PROGRAMS.get(new_stage).map(|x|x.0).unwrap_or("Choose"))
                .width(230.0).show_ui(ui,|ui|{
                    for (i,(name,_)) in crate::native_filter::PROGRAMS.iter().enumerate(){
                        if crate::native_stack::valid_stage(i){ui.selectable_value(&mut new_stage,i,*name);}
                    }
                });
            if ui.add_enabled(draft.len()<crate::native_stack::MAX_STAGES,egui::Button::new("Add effect")).clicked(){
                if crate::native_stack::valid_stage(new_stage){draft.push(new_stage);}
            }
            caption(ui,&format!("{}/8",draft.len()));
        });
        ui.add_space(8.0);
        ui.horizontal_wrapped(|ui|{
            if ui.add_enabled(crate::native_stack::validate(&draft).is_ok(),
                egui::Button::new("Apply ordered stack").fill(Color32::from_rgb(122,32,60))).clicked(){
                if active.as_ref().unwrap_or(&preset)!=&draft{tune.layers.clear_ordered();mix_changed=true;}
                app.apply_custom_native_stack(draft.clone());
            }
            if outline_button(ui,"Load current look"){draft=active.clone().unwrap_or_else(||preset.clone());}
            if outline_button(ui,"Use standard look"){
                tune.layers.clear_ordered();mix_changed=true;
                app.select_native_preset(app.settings.native_preset);draft=preset.clone();
            }
        });
        ui.add_space(8.0);
        v22_native_toggles(app,ui);
        let mut split_on=tune.layers.split.is_some();
        if ui.checkbox(&mut split_on,"Live original / processed split (1x only)").changed(){
            tune.layers.split=split_on.then_some(0.5);mix_changed=true;
        }
        if let Some(split)=tune.layers.split.as_mut(){
            mix_changed|=ui.add(egui::Slider::new(split,0.0..=1.0).text("Split position")).changed();
        }
        if outline_button(ui,"Reset layer mixes and split"){tune.layers=Default::default();mix_changed=true;}
        caption(ui,"Each occurrence has independent mix on the applied ordered stack. Apply sequence changes before editing mixes; changing sequence resets occurrence overrides. Zero skips GPU dispatch. Partial mix adds a blend pass. Split shows pre-effect processed-resolution input on left; not an upscaler comparison. Disabled automatically for FrameGen.");
        caption(ui,"This changes Horizon's own GPU output. No game shader injection or automatic engine FPS change.");
        ui.add_space(9.0);
        egui::CollapsingHeader::new("Share or import native stack JSON").show(ui,|ui|{
            if outline_button(ui,"Export draft JSON"){
                match crate::stack_share::export(&draft){Ok(s)=>app.stack_share_edit=s,Err(e)=>app.toast(e)}
            }
            ui.add(egui::TextEdit::multiline(&mut app.stack_share_edit).desired_rows(4).desired_width(ui.available_width()).char_limit(8192));
            if outline_button(ui,"Validate and load draft"){
                match crate::stack_share::import(&app.stack_share_edit){
                    Ok(v)=>{draft=v;app.toast("Validated JSON loaded into draft; click Apply to activate");},
                    Err(e)=>app.toast(e)
                }
            }
            caption(ui,"Only built-in stage IDs are accepted; importing does not execute scripts or activate effects.");
        });
    });
    if mix_changed{app.apply_native_lighting(tune);}
    egui::CollapsingHeader::new("Named looks and A/B comparison").show(ui,|ui|{named_native_looks_panel(app,ui);look_compare_controls(app,ui,false);});
    if !history_action&&draft!=original_draft{history.record(original_draft);}
    ui.ctx().data_mut(|d|{d.insert_temp(draft_id,draft);d.insert_temp(draft_id.with("new"),new_stage);d.insert_temp(draft_id.with("history"),history);});
}

fn trim_native_gallery_cache(app:&mut BoostApp,keep:&[bool]){
 let (active,inactive)=if app.native_gallery_scene==1{(&mut app.native_gameplay_preview_textures,&mut app.native_preview_textures)}else{(&mut app.native_preview_textures,&mut app.native_gameplay_preview_textures)};
 for v in inactive.iter_mut(){*v=None;}
 let loaded=active.iter().map(Option::is_some).collect::<Vec<_>>();
 for i in crate::gallery_cache::evictions(&loaded,keep,app.settings.native_preset,12){active[i]=None;}
}

// Explicitly select an individual real GPU stage, or add it to the current stack.
fn native_individual_effects(app:&mut BoostApp,ui:&mut Ui){
 let id=ui.id().with("individual-effect-search");
 let mut query=ui.data(|d|d.get_temp::<String>(id)).unwrap_or_default();
 ui.add(egui::TextEdit::singleline(&mut query).hint_text("Search individual shaders").char_limit(64));
 let entries=crate::native_look_library::effects(&query);
 let key=app.profile_key();
 let current=app.settings.native_stack_profiles.get(&key).cloned().unwrap_or_else(||crate::native_presets::PRESETS[app.settings.native_preset].stages.to_vec());
 caption(ui,&format!("{} matching stages / {} of 8 active slots",entries.len(),current.len()));
 egui::ScrollArea::vertical().max_height(230.).id_salt("individual-effects-list").show(ui,|ui|{
  for i in entries{ui.push_id(i,|ui|{ui.horizontal_wrapped(|ui|{
   ui.label(crate::native_filter::PROGRAMS[i].0);
   if ui.small_button("Select only").clicked(){app.apply_custom_native_stack(vec![i]);}
   if ui.add_enabled(current.len()<8,egui::Button::new("+ Add")).clicked(){let mut next=current.clone();next.push(i);app.apply_custom_native_stack(next);}
  });});}
 });
 caption(ui,"Select or add an effect, then Apply effects or Preview if no output is running.");
 ui.data_mut(|d|d.insert_temp(id,query));
}
fn named_native_looks_panel(app:&mut BoostApp,ui:&mut Ui){
 let id=ui.id().with("named-native-look");
 let mut name=ui.data(|d|d.get_temp::<String>(id)).unwrap_or_default();
 let mut replace=ui.data(|d|d.get_temp::<bool>(id.with("replace"))).unwrap_or(false);
 let mut deleting=ui.data(|d|d.get_temp::<bool>(id.with("delete"))).unwrap_or(false);
 if ui.add(egui::TextEdit::singleline(&mut name).hint_text("Name current GPU look").char_limit(48)).changed(){replace=false;deleting=false;}
 let exists=app.settings.named_native_looks.contains_key(name.trim());
 ui.horizontal_wrapped(|ui|{
  if exists{ui.checkbox(&mut replace,"Replace saved look");}
  if ui.add_enabled(!exists||replace,egui::Button::new("Save current look")).clicked(){
   let look=crate::compare::NativeLook::capture(&app.settings,&app.profile_key());
   match crate::native_look_library::save(&mut app.settings.named_native_looks,&name,look,replace){Ok(())=>{name=name.trim().to_owned();replace=false;app.save();app.toast("Native look saved");},Err(e)=>app.toast(e)}
  }
 });
 let names=app.settings.named_native_looks.keys().cloned().collect::<Vec<_>>();
 egui::ComboBox::from_id_salt(id.with("list")).selected_text(if exists{name.trim()}else{"Choose saved look"}).show_ui(ui,|ui|{for n in names{if ui.selectable_label(name==n,&n).clicked(){name=n;replace=false;deleting=false;}}});
 let exists=app.settings.named_native_looks.contains_key(name.trim());
 ui.horizontal_wrapped(|ui|{
  if ui.add_enabled(exists,egui::Button::new("Load / apply")).clicked(){app.load_named_native_look(name.trim());}
  if exists&&ui.small_button(if deleting{"Confirm delete"}else{"Delete saved look"}).clicked(){if deleting{app.settings.named_native_looks.remove(name.trim());app.save();name.clear();deleting=false;}else{deleting=true;}}
  if deleting&&ui.small_button("Cancel").clicked(){deleting=false;}
 });
 caption(ui,"Saved looks retain effect order, strengths, lighting and quality. Loading never starts capture or changes game resolution.");
 ui.data_mut(|d|{d.insert_temp(id,name);d.insert_temp(id.with("replace"),replace);d.insert_temp(id.with("delete"),deleting);});
}
